INSERT INTO lib_books (category_id, title, author, isbn, description, copies_total, copies_available, rent_per_day, deposit) VALUES
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Philosopher''s Stone', 'J. K. Rowling', '9788498387094', 'Turning the envelope over, his hand trembling, Harry saw a purple wax seal bearing a coat of arms; a lion, an eagle, a badger and a snake surrounding a large letter ''H''.', 2, 2, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'A Game of Thrones', 'George R. R. Martin', '9780006479888', '***A Game of Thrones*** is the inaugural novel in ***A Song of Ice and Fire***, an epic series of fantasy novels crafted by the American author **George R. R. Martin**. Published on August 1, 1996, this novel introduces readers to the richly detailed world of Westeros and Essos, where political intrigue, power struggles, and magical elements intertwine.', 3, 3, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'A Court of Mist and Fury', 'Sarah J. Maas', '9781664434448', 'Feyre has undergone more trials than one human woman can carry in her heart. Though she''s now been granted the powers and lifespan of the High Fae, she is haunted by her time Under the Mountain and the terrible deeds she performed to save the lives of Tamlin and his people.', 4, 4, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Nineteen Eighty-Four', 'George Orwell', '9780140862546', 'Nineteen Eighty-Four: A Novel, often referred to as 1984, is a dystopian social science fiction novel by the English novelist George Orwell (the pen name of Eric Arthur Blair). It was published on 8 June 1949 by Secker & Warburg as Orwell''s ninth and final book completed in his lifetime. Thematically, Nineteen Eighty-Four centres on the consequences of totalitarianism, mass surveillance, and repressive regimentation of persons and behaviours within society. Orwell, himself a democratic socialist, modelled the authoritarian government in the novel after Stalinist Russia. More broadly, the novel examines the role of truth and facts within politics and the ways in which they are manipulated.', 2, 2, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Lightning Thief', 'Rick Riordan', '9780641723445', 'Twelve-year-old Percy Jackson is on the most dangerous quest of his life. With the help of a satyr and a daughter of Athena, Percy must journey across the United States to catch a thief who has stolen the original weapon of mass destruction—Zeus’ master bolt. Along the way, he must face a host of mythological enemies determined to stop him. Most of all, he must come to terms with a father he has never known, and an Oracle that has warned him of betrayal by a friend.', 3, 3, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Chamber of Secrets', 'J. K. Rowling', '9780747545774', 'Throughout the summer holidays after his first year at Hogwarts School of Witchcraft and Wizardry, Harry Potter has been receiving sinister warnings from a house-elf called Dobby.', 4, 4, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Deathly Hallows', 'J. K. Rowling', '9783867176651', 'Harry Potter is leaving Privet Drive for the last time. But as he climbs into the sidecar of Hagrid’s motorbike and they take to the skies, he knows Lord Voldemort and the Death Eaters will not be far behind.', 2, 2, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Prisoner of Azkaban', 'J. K. Rowling', '9788475967769', 'For Harry Potter, it’s the start of another far-from-ordinary year at Hogwarts when the Knight Bus crashes through the darkness and comes to an abrupt halt in front of him.', 3, 3, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Cruel Prince', 'Holly Black', '9780316310277', '**GUARD YOUR MORTAL HEART.**', 4, 4, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'The Hobbit', 'J.R.R. Tolkien', '9782253049418', 'The Hobbit is a tale of high adventure, undertaken by a company of dwarves in search of dragon-guarded gold. A reluctant partner in this perilous quest is Bilbo Baggins, a comfort-loving unambitious hobbit, who surprises even himself by his resourcefulness and skill as a burglar.', 2, 2, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Goblet of Fire', 'J. K. Rowling', '9788000012537', 'The fourth book in the Harry Potter franchise sees Harry returning for his fourth year at Hogwarts School of Witchcraft and Wizardry, along with his friends, Ron and Hermione . There is an upcoming tournament between the three major schools of magic, with one participant selected from each school by the Goblet of Fire. When Harry''s name is drawn, even though he is not eligible and is a fourth player, he must compete in the dangerous contest.', 3, 3, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='นิยายแฟนตาซี'), 'Harry Potter and the Order of the Phoenix', 'J. K. Rowling', '9788372780966', 'After the Dementors’ attack on his cousin Dudley, Harry knows he is about to become Voldemort’s next target.', 4, 4, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'A Brief History of Time', 'Stephen Hawking', '9789879317679', 'Stephen Hawking''s ‘A Brief History of Time* has become an international publishing phenomenon. Translated into thirty languages, it has sold over ten million copies worldwide and lives on as a science book that continues to captivate and inspire new readers each year. When it was first published in 1988 the ideas discussed in it were at the cutting edge of what was then known about the universe. In the intervening twenty years there have been extraordinary advances in the technology of observing both the micro- and macro-cosmic world. Indeed, during that time cosmology and the theoretical sciences have entered a new golden age . Professor Hawking is one of the major scientists and thinker...', 2, 2, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'A short history of nearly everything', 'Bill Bryson', '9788478713806', 'A Short History of Nearly Everything by American author Bill Bryson is a popular science book that explains some areas of science, using easily accessible language that appeals more so to the general public than many other books dedicated to the subject. It was one of the bestselling popular science books of 2005 in the United Kingdom, selling over 300,000 copies.', 3, 3, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Man Who Mistook His Wife for a Hat', 'Oliver Sacks', '9780593466674', 'In his most extraordinary book, “one of the great clinical writers of the twentieth century” *(The New York Times)* recounts the case histories of patients lost in the bizarre, apparently inescapable world of neurological disorders.', 4, 4, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Cosmos', 'Carl Sagan', '9781559603140', 'This book is about science in its broadest human context, how science and civilization grew up together. It is the story of our long journey of discovery and the forces and individuals who helped to shape modern science, including Democritus, Hypatia, Kepler, Newton, Huygens, Champollion, Lowell and Humason. The book also explores spacecraft missions of discovery of the nearby planets, the research in the Library of ancient Alexandria, the human brain, Egyptian hieroglyphics, the origin of life, the death of the Sun, the evolution of galaxies and the origins of matter, suns and worlds. The author retraces the fifteen billion years of cosmic evolution that have transformed matter into life...', 2, 2, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Demon-Haunted World', 'Carl Sagan', '9780345409461', 'A prescient warning of a future we now inhabit, where fake news stories and Internet conspiracy theories play to a disaffected American populace', 3, 3, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Über die spezielle und die allgemeine Relativitätstheorie', 'Albert Einstein', '9780879759797', 'Einstein''s own explanation of his theory for those who do not have a mathematical background and are unfamiliar with physics.', 4, 4, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Brain Rules', 'John Medina', '9780979777745', 'Most of us have no idea what''s really going on inside our heads. Yet brain scientists have uncovered details every business leader, parent, and teacher should know—such as the brain''s need for physical activity to work at its best.How do we learn? What exactly do sleep and stress do to our brains? Why is multi-tasking a myth? Why is it so easy to forget—and so important to repeat new knowledge? Is it true that men and women have different brains?In Brain Rules, molecular biologist John Medina shares his lifelong interest in how the brain sciences might influence the way we teach our children and the way we work. In each chapter, he describes a Brain Rule—what scientists know for sure abou...', 2, 2, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Intelligent Man''s Guide to Science', 'Isaac Asimov', '9788401480058', 'Reports on recent advances in the physical and biological sciences to aid the general reader in understanding modern scientific phenomena.', 3, 3, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Siete breves lecciones de física', 'Carlo Rovelli', '9786257118026', 'An introduction to modern physics by a founder of the loop quantum gravity theory shares seven succinct lessons on topics ranging from general relativity and quantum mechanics to elementary particles and black holes.', 4, 4, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'Bad Science', 'Ben Goldacre', '9781407438719', 'Full of spleen, this will be a hilarious, invigorating and informative journey through the world of Bad Science.When Dr Ben Goldacre saw someone on daytime TV dipping her feet in an ''Aqua Detox'' footbath, releasing her toxins into the water, turning it brown, he thought he''d try the same at home. ''Like some kind of Johnny Ball cum Witchfinder General'', using his girlfriend''s Barbie doll, he gently passed an electrical current through the warm salt water. It turned brown. In his words: ''before my very eyes, the world''s first Detox Barbie was sat, with her feet in a pool of brown sludge, purged of a weekend''s immorality.''Dr Ben Goldacre is the author of the Bad Science column in the Guardia...', 2, 2, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Fabric of the Cosmos', 'Brian Greene', '9780375727207', 'A magnificent challenge to conventional ideas'' Financial Times''I thoroughly enjoyed this book. It manages to be both challenging and entertaining: it is highly recommended'' the Independent''(Greene) send(s) the reader''s imagination hurtling through the universe on an astonishing ride. As a popularizer of exquisitely abstract science, he is both a skilled and kindly explicator'' the New York Times''Greene is as elegant as ever, cutting through the fog of complexity with insight and clarity; space and time become putty in his hands'' Los Angeles Times Book Review', 3, 3, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วิทยาศาสตร์'), 'The Magic of Reality', 'Richard Dawkins', '9780857531940', 'What are things made of? What is the sun? Why is there night and day, winter and summer? Why do bad things happen? Are we alone?', 4, 4, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Sapiens', 'Yuval Noah Harari', '9781716994982', 'From a renowned historian comes a groundbreaking narrative of humanity’s creation and evolution—a #1 international bestseller—that explores the ways in which biology and history have defined us and enhanced our understanding of what it means to be “human.”', 2, 2, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Guns, Germs, and Steel', 'Jared Diamond', '9783596145393', 'An epic detective story that offers a gripping expose on why the world is so unequal. Professor Jared Diamond traveled the globe for over 30 years trying to answer this question.', 3, 3, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Manifest der Kommunistischen Partei', 'Karl Marx', '9780853459361', 'Available under a Creative Commons Attribution-ShareAlike License: http://www.marxists.org/archive/marx/works/1848/communist-manifesto/', 4, 4, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'A history of the modern world', 'R. R. Palmer', '9780072316551', 'Conceived and written as a history of the modern world rather than a truncated Western Civilization book, this text is one of the most highly praised history texts ever published. It has been adopted at more than 1000 schools and has been translated into six languages. Lloyd Kramer joins the author team for this ninth edition that includes two new color inserts highlighting fine art, additional pedagogy to guide students through challenging material, and full, up-to-date inclusion of current events. First published in 1950, translated into six languages, is used in more than 1,000 colleges and universities as well as many high school advanced placement courses. The second edition (1956), ...', 2, 2, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Eichmann in Jerusalem', 'Hannah Arendt', '9781101004760', '**Eichmann in Jerusalem: A Report on the Banality of Evil** is a 1963 book by political theorist *Hannah Arendt*. Arendt, a Jew who fled Germany during Adolf Hitler''s rise to power, reported on Adolf Eichmann''s trial for The New Yorker. A revised and enlarged edition was published in 1964.', 3, 3, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Souls of Black Folk', 'W. E. B. Du Bois', '9781975500634', 'Du Bois'' 1903 collection of essays is a thoughtful, articulate exploration of the moral and intellectual issues surrounding the perception of blacks within American society.', 4, 4, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Collapse', 'Jared Diamond', '9780713998627', '"In his Pulitzer Prize-winning bestseller Guns, Germs, and Steel, Jared Diamond examined how and why Western civilizations developed the technologies and immunities that allowed them to dominate much of the world. Now, Diamond probes the other side of the equation: What caused some of the great civilizations of the past to collapse into ruin, and what can we learn from their fates?" "As in Guns, Germs, and Steel, Diamond weaves an all-encompassing global thesis through a series of historical-cultural narratives. Moving from the prehistoric Polynesian culture on Easter Island to the formerly flourishing Native American civilizations of the Anasazi and the Maya, the doomed medieval Viking c...', 2, 2, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Silk Roads', 'Peter Frankopan', '9781408889930', '"Our world was made on and by the Silk Roads. For millennia it was here that East and West encountered each other through trade and conquest, leading to the spread of ideas and cultures, the birth of the world''s great religions, the appetites for foreign goods that drove economies and the growth of nations. From the first cities in Mesopotamia to the growth of Greece and Rome to the depredations by the Mongols and the Black Death to the Great Game and the fall of Communism, the fate of the West has always been inextricably linked to the East. The Silk Roads vividly captures the importance of the networks that crisscrossed the spine of Asia and linked the Atlantic with the Pacific, the Med...', 3, 3, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Lessons of History', 'Will Durant', '9787220093104', 'Written by the authors of the 10 volume *The Story of Civilization*, this short (fewer than 120 pages) work notes "events and comments that might illuminate present affairs, future probabilities, the nature of man, and the conduct of states." Its 13 chapters discuss historiography (what is history), history and the earth, history and biology, race, character, morals, religion, economics, socialism, government, war, growth and decay. The final chapter asks, "Is progress real?"', 4, 4, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Muqaddimah, an introduction to history', 'Ibn Khaldūn', '9780691099460', 'This prolegomenon was written in the 14th century by the Arab scholar Ibn Khaldūn, & laid the intellectual foundations for philosophy of history, sociology, ethnography & economics. This translation was first published in 1958 in three volumes.', 2, 2, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'The Alhambra', 'Washington Irving', '9788495856654', 'Verhalen over het gebouwencomplex in Granada, dat eigendom was van de laatste islamitische vorsten in Spanje.', 3, 3, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='ประวัติศาสตร์'), 'Traditions & encounters', 'Jerry H. Bentley', '9780073513324', 'Traditions & Encounters: A Brief Global History brings focus to the human experience. It turns the story of world history into a cohesive narrative by putting events into perspective and creating a framework for cross-cultural comparisons. It tells the story of people in history, the traditions they embraced, and the encounters with other cultures that brought about inevitable change. - Back cover.', 4, 4, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Wuthering Heights', 'Emily Brontë', '9782322182732', 'Wuthering Heights is an 1847 novel by Emily Brontë, initially published under the pseudonym Ellis Bell. It concerns two families of the landed gentry living on the West Yorkshire moors, the Earnshaws and the Lintons, and their turbulent relationships with Earnshaw''s adopted son, Heathcliff. The novel was influenced by Romanticism and Gothic fiction.', 2, 2, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Alice''s Adventures in Wonderland', 'Lewis Carroll', '9788477026709', 'Alice''s Adventures in Wonderland (commonly Alice in Wonderland) is an 1865 English children''s novel by Lewis Carroll. A young girl named Alice falls through a rabbit hole into a fantasy world of anthropomorphic creatures. It is seen as an example of the literary nonsense genre.', 3, 3, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Prince', 'Niccolò Machiavelli', '9780553897371', 'The Prince (Italian: Il Principe [il ˈprintʃipe]; Latin: De Principatibus) is a 16th-century political treatise written by Italian diplomat and political theorist Niccolò Machiavelli as an instruction guide for new princes and royals. The general theme of The Prince is of accepting that the aims of princes – such as glory and survival – can justify the use of immoral means to achieve those ends.', 4, 4, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Invisible Man', 'H. G. Wells', '9781537808352', 'This book is the story of Griffin, a scientist who creates a serum to render himself invisible, and his descent into madness that follows.', 2, 2, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Moby Dick', 'Herman Melville', '9781547220892', '"Command the murderous chalices! Drink ye harpooners! Drink and swear, ye men that man the deathful whaleboat''s bow -- Death to Moby Dick!" So Captain Ahab binds his crew to fulfil his obsession -- the destruction of the great white whale. Under his lordly but maniacal command the Pequod''s commercial mission is perverted to one of vengeance. To Ahab, the monster that destroyed his body is not a creature, but the symbol of "some unknown but still reasoning thing." Uncowed by natural disasters, ill omens, even death, Ahab urges his ship towards "the undeliverable, nameless perils of the whale."', 3, 3, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Hamlet', 'William Shakespeare', '9789873874109', 'In this quintessential Shakespeare tragedy, a young prince''s halting pursuit of revenge for the murder of his father unfolds in a series of highly charged confrontations that have held audiences spellbound for nearly four centuries. Those fateful exchanges, and the anguished soliloquies that precede and follow them, probe depths of human feeling rarely sounded in any art.', 4, 4, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Time Machine', 'H. G. Wells', '9788175992955', 'The Time Traveller, a dreamer obsessed with traveling through time, builds himself a time machine and, much to his surprise, travels over 800,000 years into the future. He lands in the year 802701: the world has been transformed by a society living in apparent harmony and bliss, but as the Traveler stays in the future he discovers a hidden barbaric and depraved subterranean class. Wells''s transparent commentary on the capitalist society was an instant bestseller and launched the time-travel genre.', 2, 2, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Jane Eyre', 'Charlotte Brontë', '9781434615701', 'The novel is set somewhere in the north of England. Jane''s childhood at Gateshead Hall, where she is emotionally and physically abused by her aunt and cousins; her education at Lowood School, where she acquires friends and role models but also suffers privations and oppression; her time as the governess of Thornfield Hall, where she falls in love with her Byronic employer, Edward Rochester; her time with the Rivers family, during which her earnest but cold clergyman cousin, St John Rivers, proposes to her. Will she or will she not marry him?', 3, 3, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The Secret Garden', 'Frances Hodgson Burnett', '9780582426597', 'A ten-year-old orphan comes to live in a lonely house on the Yorkshire moors where she discovers an invalid cousin and the mysteries of a locked garden.', 4, 4, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'A Tale of Two Cities', 'Charles Dickens', '9780192817716', 'A Tale of Two Cities is a historical novel published in 1859 by Charles Dickens, set in London and Paris before and during the French Revolution. The novel tells the story of the French Doctor Manette, his 18-year-long imprisonment in the Bastille in Paris, and his release to live in London with his daughter Lucie whom he had never met. The story is set against the conditions that led up to the French Revolution and the Reign of Terror. In the Introduction to the Encyclopedia of Adventure Fiction, critic Don D''Ammassa argues that it is an adventure novel because the protagonists are in constant danger of being imprisoned or killed.', 2, 2, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'Slaughterhouse-Five', 'Kurt Vonnegut', '9780613647885', 'Slaughterhouse-Five is one of the world''s great anti-war books. Centering on the infamous fire-bombing of Dresden, Billy Pilgrim''s odyssey through time reflects the mythic journey of our own fractured lives as we search for meaning in what we are afraid to know.', 3, 3, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='วรรณกรรมคลาสสิก'), 'The War of the Worlds', 'H. G. Wells', '9781412196956', 'The ultimate science fiction classic: for more than one hundred years, this compelling tale of the Martian invasion of Earth has enthralled readers with a combination of imagination and incisive commentary on the imbalance of power that continues to be relevant today. The style is revolutionary for its era, employing a sophisticated first and third person account of the events which is both personal and focused on the holistic downfall of Earth''s society. The Martians, as evil, mechanical and unknown a threat they are, remain daunting in today''s society, where, despite technology''s mammoth advances, humanity''s hegemony over Earth is yet to be called into question. In Well''s introduction t...', 4, 4, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Introduction to Algorithms', 'Thomas H. Cormen', '9780070131514', 'This book provides a comprehensive introduction to the modern study of computer algorithms. It presents many algorithms and covers them in considerable depth, yet makes their design and analysis accessible to all levels of readers. We have tried to keep explanations elementary without sacrificing depth of coverage or mathematical rigor. Each chapter presents an algorithm, a design technique, an application area, or a related topic. Algorithms are described in English and in a "pseudocode" designed to be readable by anyone who has done a little programming. The book contains over 260 figrues illustrating how the algorithms work. Since we emphasize efficiency as a design criterion, we inclu...', 2, 2, 11, 220),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Software Engineering', 'Roger S. Pressman', '9788448132149', NULL, 3, 3, 8, 160),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The Pragmatic Programmer', 'Andy Hunt', '9788131722428', 'The Pragmatic Programmer is one of those rare tech audiobooks you’ll listen, re-listen, and listen to again over the years. Whether you’re new to the field or an experienced practitioner, you’ll come away with fresh insights each and every time.', 4, 4, 5, 100),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Hackers', 'Steven Levy', '9780140232691', 'Today, technology is cool. Owning the most powerful computer, the latest high-tech gadget, and the whizziest website is a status symbol on a par with having a flashy car or a designer suit. And a media obsessed with the digital explosion has reappropriated the term "computer nerd" so that it''s practically synonymous with "entrepreneur." Yet, a mere fifteen years ago, wireheads hooked on tweaking endless lines of code were seen as marginal weirdos, outsiders whose world would never resonate with the mainstream. That was before one pioneering work documented the underground computer revolution that was about to change our world forever.', 2, 2, 12, 240),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'JavaScript', 'David Flanagan', '9788565837194', 'JavaScript is a powerful, object-based scripting language; JavaScript programs can be embedded directly into HTML web pages. When combined with the Document Object Model (DOM) defined by a web browser, JavaScript allows you to create Dynamic HTML (DHTML) content and interactive client-side web applications. JavaScript syntax is based on the popular programming languages C, C++, and Java, which makes it familiar and easy to learn for experienced programmers. At the same time, JavaScript is an interpreted scripting language, providing a flexible, forgiving environment in which new programmers can learn.', 3, 3, 9, 180),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Automate the Boring Stuff with Python', 'Al Sweigart', '9781593279929', 'If you''ve ever spent hours renaming files or updating hundreds of spreadsheet cells, you know how tedious tasks like these can be. But what if you could have your computer do them for you? In Automate the Boring Stuff with Python, you''ll learn how to use Python to write programs that do in minutes what would take you hours to do by hand—no prior programming experience required. Once you''ve mastered the basics of programming, you''ll create Python programs that effortlessly perform useful and impressive feats of automation to:', 4, 4, 6, 120),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The art of computer programming', 'Donald Knuth', '9780201853933', NULL, 2, 2, 13, 260),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Structure and Interpretation of Computer Programs (SICP)', 'Harold Abelson', '9780262510875', '> **Wizard Book** n. Hal Abelson''s, Jerry Sussman''s and Julie Sussman''s Structure and Interpretation of Computer Programs (MIT Press, 1984; ISBN 0-262-01077-1), an excellent computer science text used in introductory courses at MIT. So called because of the wizard on the jacket. One of the bibles of the LISP/Scheme world. Also, less commonly, known as the Purple Book.', 3, 3, 10, 200),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The Mythical Man-Month', 'Frederick P. Brooks', '9780201006506', 'Classic text on the human side of software engineering, containing essays on the management of software teams, projections about how computer languages and tools will evolve, and philosophical speculation. Unlike most other books about computing, Brooks'' work has been remarkably enduring, remaining in print for at least four decades. The book is most famous for its statement of Brooks'' Law: "adding manpower to a late software project makes it later".', 4, 4, 7, 140),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'Code', 'Charles Petzold', '9780735605053', 'What do flashlights, the British invasion, black cats, and seesaws have to do with computers? In CODE, they show us the ingenious ways we manipulate language and invent new means of communicating with each other. And through CODE, we see how this ingenuity and our very human compulsion to communicate have driven the technological innovations of the past two centuries.', 2, 2, 14, 280),
  ((SELECT category_id FROM lib_categories WHERE name='คอมพิวเตอร์'), 'The C++ programming language', 'Bjarne Stroustrup', '9783827316608', 'The C++ Programming tome, written by the father of C++ himself, Bjarne Stroustrup. The premier book on the subject of C++ Programming.', 3, 3, 11, 220)
